/*
 * W1-T26 acceptance check 3: the generator reproduces the committed critical values (ARCHITECTURE §5.1: tables that need a
 * transcendental function are generated by a script under scripts/tables/, committed as integers, and re-checked by CI).
 *
 *   - The generator's text is the committed file's bytes, and its integers are the ones packages/sim/spec exports.
 *   - The integers are right. Each entry c is the least integer with P(χ² > c / 1000) ≤ α, and this file checks that by a method
 *     that shares no code with the generator: exact fixed-point arithmetic on BigInt, 400 bits, summing the all-positive power
 *     series of the incomplete gamma function with an exact Γ and e^y by its Taylor series. It evaluates the survival function at c / 2000
 *     and at (c − 1) / 2000, and wants the first at most α and the second above it. (A 70-digit Python Decimal run of the same series
 *     agreed with every one of the 510 entries [measured 2026-11-04].)
 *   - The generator's refusal to write a table whose roundings depend on the platform's libm is exercised on inputs close to an integer.
 *   - The command line writes, checks and fails as the header of the script says, and `bun scripts/vectors.ts --check` includes it.
 */
import { afterAll, describe, expect, test } from 'bun:test'
import { spawnSync } from 'node:child_process'
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { CRITICAL, CRITICAL_MAX_DF, CRITICAL_SCALE } from '../../packages/sim/spec'
import { LEVELS, MARGIN, MAX_DF, SCALE, TABLE_FILE, ceilWithMargin, checkCritical, computeTable, criticalValue, expectedSource, renderTable } from '../../scripts/tables/chi-square-critical'
import { check } from '../../scripts/vectors'

const root = path.resolve(import.meta.dirname, '../..')
const committed = readFileSync(path.join(root, TABLE_FILE), 'utf8')

describe('the committed critical values', () => {
  test('are exactly what the generator writes', () => {
    expect(expectedSource()).toBe(committed)
    expect(checkCritical(root)).toBeNull()
  })

  test('hold the generator\'s integers, which packages/sim/spec exports under the generator\'s constants', () => {
    const { values } = computeTable()
    expect([CRITICAL_SCALE, CRITICAL_MAX_DF]).toEqual([SCALE, MAX_DF])
    expect(Object.keys(CRITICAL)).toEqual(LEVELS.map((l) => l.key))
    for (const { key } of LEVELS) {
      expect(CRITICAL[key]).toEqual(values[key])
      expect(CRITICAL[key]).toHaveLength(MAX_DF + 1)
    }
  })

  test('are a generated file that says so, and are plain integers', () => {
    expect(committed.startsWith('// GENERATED by `bun scripts/tables/chi-square-critical.ts --write`')).toBe(true)
    expect(committed.match(/export const /g)).toHaveLength(3)
    expect(committed.split('\n').filter((line) => !line.startsWith('//')).join('\n')).not.toMatch(/Math\./)
    for (const { key } of LEVELS) {
      const body = committed.slice(committed.indexOf(`'${key}': [`))
      expect(body.slice(0, body.indexOf(']') + 1)).toMatch(/^'[0-9e-]+': \[(\s*\d+,)+\s*\]$/)
    }
    expect(renderTable(computeTable().values)).toBe(committed)
  })

  test('start at 0 degrees of freedom with 0, rise with df, and put the 1e-4 value above the 1e-3 value', () => {
    for (const { key } of LEVELS) {
      expect(CRITICAL[key][0]).toBe(0)
      for (let df = 1; df <= MAX_DF; df++) expect(CRITICAL[key][df], `${key} df ${df}`).toBeGreaterThan(CRITICAL[key][df - 1])
    }
    for (let df = 1; df <= MAX_DF; df++) expect(CRITICAL['1e-4'][df]).toBeGreaterThan(CRITICAL['1e-3'][df])
  })

  test('match the closed form for 2 degrees of freedom, where P(χ² > x) = e^(−x/2): x = 2 ln(1/α) rounded up', () => {
    expect(CRITICAL['1e-3'][2]).toBe(Math.ceil(1000 * 2 * Math.log(1000)))
    expect(CRITICAL['1e-4'][2]).toBe(Math.ceil(1000 * 2 * Math.log(10000)))
    expect([CRITICAL['1e-3'][2], CRITICAL['1e-4'][2]]).toEqual([13816, 18421])
  })

  test('was rounded with room to spare: the least distance from a computed value to an integer is far above the margin', () => {
    const { margin } = computeTable()
    expect(margin).toBeGreaterThanOrEqual(MARGIN)
    expect(margin).toBeGreaterThan(10 * MARGIN) // observed 1.2e-4 of a unit [measured 2026-11-04, bun 1.3.14]; a libm error here is about 1e-12 [estimated]
  })
})

// ---------------------------------------------------------------------------------------------------------------------------
// An independent check of the values: exact fixed-point arithmetic

const BITS = 400n
const ONE = 1n << BITS
const mul = (a: bigint, b: bigint): bigint => (a * b) >> BITS
const div = (a: bigint, b: bigint): bigint => (a << BITS) / b

/** e^x for a fixed-point x ≥ 0: halve x until it is under 1, sum the Taylor series, and square back. */
function exp(x: bigint): bigint {
  let r = x
  let squarings = 0
  while (r >= ONE) {
    r >>= 1n
    squarings++
  }
  let term = ONE
  let sum = ONE
  for (let n = 1n; term > 0n; n++) {
    term = mul(term, r) / n
    sum += term
  }
  for (let i = 0; i < squarings; i++) sum = mul(sum, sum)
  return sum
}

/** The square root of a fixed-point x: the integer square root of x · 2^BITS, by Newton's method. */
function sqrt(x: bigint): bigint {
  const n = x << BITS
  let r = 1n << BigInt(Math.ceil(n.toString(2).length / 2) + 1)
  for (;;) {
    const next = (r + n / r) >> 1n
    if (next >= r) return r
    r = next
  }
}

/** arctan(1/n), by its series. */
function arctanInverse(n: bigint): bigint {
  const n2 = n * n
  let term = ONE / n
  let sum = term
  for (let k = 3n, sign = -1n; term > 0n; k += 2n, sign = -sign) {
    term /= n2
    sum += sign * (term / k)
  }
  return sum
}
/** π by Machin's formula. */
const PI = 16n * arctanInverse(5n) - 4n * arctanInverse(239n)
const SQRT_PI = sqrt(PI)

const factorial = (n: number): bigint => {
  let f = 1n
  for (let i = 2n; i <= BigInt(n); i++) f *= i
  return f
}

/** Γ(df / 2 + 1), exactly: (df/2)! for an even df, and (df/2)·(2m)!/(4^m m!)·√π for an odd one with df = 2m + 1. */
function gammaOfHalfPlusOne(df: number): bigint {
  if (df % 2 === 0) return factorial(df / 2) << BITS
  const m = (df - 1) / 2
  const gammaHalf = mul(div(factorial(2 * m) << BITS, (4n ** BigInt(m) * factorial(m)) << BITS), SQRT_PI)
  return mul((BigInt(df) << BITS) / 2n, gammaHalf)
}

/** Q(df/2, y) = 1 − P(df/2, y), with P by y^a e^(−y) ÷ Γ(a + 1) times the all-positive series Σ y^n ÷ ((a + 1) … (a + n)). */
function survival(df: number, y: bigint): bigint {
  let power = ONE
  for (let i = 0; i < Math.floor(df / 2); i++) power = mul(power, y)
  if (df % 2 === 1) power = mul(power, sqrt(y))
  const front = div(div(power, exp(y)), gammaOfHalfPlusOne(df))
  let term = ONE
  let sum = ONE
  for (let n = 1n; term > 0n; n++) {
    term = (mul(term, y) * 2n) / (BigInt(df) + 2n * n)
    sum += term
  }
  return ONE - mul(front, sum)
}

describe('the critical values, against exact arithmetic that shares no code with the generator', () => {
  const at = (c: number): bigint => (BigInt(c) << BITS) / 2000n

  test('the exact survival function is itself right: it gives e^(−y) for 2 degrees of freedom and erfc(1) for 1', () => {
    // Q(1, y) = e^(−y), so Q(1, ln 1000) · 1000 = 1; with y = 6.907755…, within 1e-9 of it.
    const y = (6907755278982137n << BITS) / 10n ** 15n
    const q = survival(2, y)
    expect(Number((q * 10n ** 12n * 1000n) >> BITS)).toBeGreaterThan(1e12 - 1e4)
    expect(Number((q * 10n ** 12n * 1000n) >> BITS)).toBeLessThan(1e12 + 1e4)
    // Q(1/2, 1) = erfc(1) = 0.157299207050285…
    const erfc1 = Number((survival(1, ONE) * 10n ** 15n) >> BITS) / 1e15
    expect(Math.abs(erfc1 - 0.157299207050285)).toBeLessThan(1e-12)
    // The recurrence Q(a + 1, y) = Q(a, y) + y^a e^(−y) ÷ Γ(a + 1), at a = 1/2 and y = 2.
    const lhs = Number((survival(3, ONE * 2n) * 10n ** 15n) >> BITS) / 1e15
    const rhs = Number((survival(1, ONE * 2n) * 10n ** 15n) >> BITS) / 1e15 + (Math.SQRT2 * Math.exp(-2)) / (0.5 * Math.sqrt(Math.PI))
    expect(Math.abs(lhs - rhs)).toBeLessThan(1e-12)
  })

  test('every entry is the least integer whose survival probability is at most its level: Q(c / 2000) ≤ α < Q((c − 1) / 2000)', () => {
    for (const { key, alpha } of LEVELS) {
      const denominator = BigInt(Math.round(1 / alpha))
      for (let df = 1; df <= MAX_DF; df++) {
        const c = CRITICAL[key][df]
        expect(survival(df, at(c)) * denominator <= ONE, `${key} df ${df}: ${c} is not enough`).toBe(true)
        expect(survival(df, at(c - 1)) * denominator > ONE, `${key} df ${df}: ${c - 1} would do`).toBe(true)
      }
    }
  })

  test('the generator\'s roots are accurate: at each of the 510 critical values it computes, the exact survival probability is within 1e-12 of its level', () => {
    // A double x is an integer multiple of 2^-52 in [2^k, 2^(k+1)) for k >= 1 and so converts to fixed point exactly.
    const exactly = (x: number): bigint => {
      const whole = Math.floor(x)
      return (BigInt(whole) << BITS) + ((BigInt((x - whole) * 2 ** 52) << BITS) >> 52n)
    }
    let worst = 0
    for (const { key, alpha } of LEVELS) {
      const denominator = BigInt(Math.round(1 / alpha))
      for (let df = 1; df <= MAX_DF; df++) {
        const q = survival(df, exactly(criticalValue(df, alpha)) / 2n)
        const gap = q * denominator > ONE ? q * denominator - ONE : ONE - q * denominator
        const relative = Number((gap * 10n ** 18n) / ONE) / 1e18
        if (relative > worst) worst = relative
        expect(relative, `${key} df ${df}`).toBeLessThan(1e-12)
      }
    }
    expect(worst).toBeGreaterThan(0) // the roots are doubles, not exact: observed 2.4e-13 at 1e-4, df 255 [measured 2026-11-04, bun 1.3.14]
  })
})

// ---------------------------------------------------------------------------------------------------------------------------
// The guard against the platform's libm

describe('ceilWithMargin', () => {
  test('rounds up and reports the distance from the nearest integer', () => {
    const forty = ceilWithMargin(10.4, 'x')
    expect(forty.value).toBe(11)
    expect(forty.distance).toBeCloseTo(0.4, 12)
    expect(ceilWithMargin(10.9, 'x').value).toBe(11)
    expect(ceilWithMargin(10.5, 'x').distance).toBe(0.5)
  })

  test('refuses a value within MARGIN of an integer, since a different libm could round it the other way', () => {
    expect(() => ceilWithMargin(10 + MARGIN / 2, 'level 1e-3, df 4')).toThrow(/level 1e-3, df 4: .* is only .* of a table unit from an integer/)
    expect(() => ceilWithMargin(11 - MARGIN / 2, 'x')).toThrow(/libm/)
    expect(() => ceilWithMargin(12, 'x')).toThrow(/libm/) // an exact integer is refused too: 12 could be computed as 11.999999999999998
    expect(() => ceilWithMargin(10 + 2 * MARGIN, 'x')).not.toThrow()
  })
})

// ---------------------------------------------------------------------------------------------------------------------------
// The command line, and the gate that runs it

describe('bun scripts/tables/chi-square-critical.ts', () => {
  const scratch: string[] = []
  afterAll(() => scratch.forEach((dir) => rmSync(dir, { recursive: true, force: true })))
  const tree = (): string => {
    const dir = mkdtempSync(path.join(tmpdir(), 'enginespace-critical-'))
    scratch.push(dir)
    mkdirSync(path.join(dir, 'packages/sim/spec'), { recursive: true })
    return dir
  }
  const run = (...args: string[]) => {
    const result = spawnSync(process.execPath, [path.join(root, 'scripts/tables/chi-square-critical.ts'), ...args], { cwd: root, encoding: 'utf8' })
    return { status: result.status, stdout: result.stdout, stderr: result.stderr }
  }

  test('--check passes on the repository, and says how far from a rounding the least entry is', () => {
    const result = run('--check')
    expect(result.stderr).toBe('')
    expect(result.status).toBe(0)
    expect(result.stdout).toContain('is what the generator writes (2 levels, df 0 to 255, smallest margin 1.16e-4 of a unit)')
  })

  test('--write writes the committed bytes into the tree it is given, and --check then passes there', () => {
    const dir = tree()
    expect(run('--check', '--root', dir).status).toBe(1)
    expect(run('--write', '--root', dir).status).toBe(0)
    expect(readFileSync(path.join(dir, TABLE_FILE), 'utf8')).toBe(committed)
    expect(run('--check', '--root', dir).status).toBe(0)
  })

  test('--check fails on a table that has changed by one unit, and says where', () => {
    const dir = tree()
    writeFileSync(path.join(dir, TABLE_FILE), committed.replace('0, 10828, 13816', '0, 10828, 13817'))
    const result = run('--check', '--root', dir)
    expect(result.status).toBe(1)
    expect(result.stderr).toContain('is not what the generator writes (first difference on line 14)')
    expect(result.stderr).toContain('--write')
  })

  test('--check fails on a missing table and exits 2 with the usage on no mode or a bad argument', () => {
    const missing = run('--check', '--root', tree())
    expect(missing.status).toBe(1)
    expect(missing.stderr).toContain('is missing')
    for (const args of [[], ['--nope'], ['--root']]) {
      const result = run(...args)
      expect(result.status, args.join(' ')).toBe(2)
      expect(result.stderr).toContain('usage: bun scripts/tables/chi-square-critical.ts')
    }
  })

  test('scripts/vectors.ts --check, which verify:determinism runs, fails on a stale table too', () => {
    const dir = tree()
    mkdirSync(path.join(dir, 'packages/sim/core'), { recursive: true })
    copyFileSync(path.join(root, 'packages/sim/core/exp-quantiles.ts'), path.join(dir, 'packages/sim/core/exp-quantiles.ts'))
    writeFileSync(path.join(dir, TABLE_FILE), committed)
    // No model is asked for, so the fixtures and slices a tree would need are not either: this reaches only the tables.
    expect(check(dir, [])).toEqual([])
    writeFileSync(path.join(dir, TABLE_FILE), committed.replace('0, 10828, 13816', '0, 10828, 13817'))
    const problems = check(dir, [])
    expect(problems).toHaveLength(1)
    expect(problems[0]).toContain('packages/sim/spec/critical.ts is not what the generator writes')
  })
})
